import{describe,it,expect}from"vitest";import{CHIEF_MINISTERS_DATA,filterCMData,getPartyClass}from"../../frontend/state-chief-ministers-explorer/script.js";describe("State Chief Ministers Explorer",()=>{it("should have a comprehensive dataset of Chief Ministers across states and UTs",()=>{expect(Array.isArray(CHIEF_MINISTERS_DATA)).toBe(!0),expect(CHIEF_MINISTERS_DATA.length).toBeGreaterThanOrEqual(30),CHIEF_MINISTERS_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("state"),expect(e).toHaveProperty("cmName"),expect(e).toHaveProperty("party"),expect(e).toHaveProperty("capital"),expect(e).toHaveProperty("region"),expect(e).toHaveProperty("facts"),expect(Array.isArray(e.facts)).toBe(!0),expect(e.facts.length).toBeGreaterThan(0)})}),it("should filter CM data by search term",()=>{const e=filterCMData(CHIEF_MINISTERS_DATA,"Uttar Pradesh");expect(e.length).toBe(1),expect(e[0].cmName).toBe("Yogi Adityanath");const t=filterCMData(CHIEF_MINISTERS_DATA,"Stalin");expect(t.length).toBe(1),expect(t[0].state).toBe("Tamil Nadu")}),it("should filter CM data by region",()=>{const e=filterCMData(CHIEF_MINISTERS_DATA,"","South","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.region).toBe("South"))}),it("should filter CM data by party category",()=>{const e=filterCMData(CHIEF_MINISTERS_DATA,"","all","BJP");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.partyCategory).toBe("BJP"));const t=filterCMData(CHIEF_MINISTERS_DATA,"","all","INC");expect(t.length).toBeGreaterThan(0),t.forEach(e=>expect(e.partyCategory).toBe("INC"))}),it("should return correct CSS classes for party categories",()=>{expect(getPartyClass("BJP")).toBe("party-bjp"),expect(getPartyClass("INC")).toBe("party-inc"),expect(getPartyClass("AAP")).toBe("party-aap"),expect(getPartyClass("Regional")).toBe("party-regional")})});